package sylva.model;

import sylva.dsa.*;
import sylva.model.Rules.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;

/** Deterministic 60 Hz game rules. Rendering and input are owned by the Swing view. */
public final class GameEngine implements Serializable {
    private static final long serialVersionUID=1L;private static final double STEP=1.0/60;
    public Difficulty difficulty=Difficulty.RESOLUTE;public Phase phase=Phase.READY;public int health=100,coins=200,wave=1,nextId=1,totalKills,recordId;public double time,accumulator,spawnClock;public boolean paused;public int speed=1;
    public ArrayList<Tower> towers=new ArrayList<>();public ArrayList<Invader> enemies=new ArrayList<>();public ProjectileList<Projectile> projectiles=new ProjectileList<>();public CircularQueue<EnemySpec> queue=new CircularQueue<>(128);public DecisionStack<Decision> undo=new DecisionStack<>(),redo=new DecisionStack<>();public EnemyIndex<Invader> enemyIndex=new EnemyIndex<>();public WaveHistory<WaveRecord> history=new WaveHistory<>();public ArrayList<Operation> operations=new ArrayList<>();public ArrayList<BuildCell> path=new ArrayList<>();
    public int waveTotal, waveKills,waveLeaked;public double waveDamage;public int selectedTowerId=-1;private int seed=2764293;private transient Rules.World world;private transient Consumer<String> notices=m->{};private transient MaxHeap<Invader> lastHeap;private transient ArrayList<Map<String,Object>> events=new ArrayList<>();
    public record Operation(String structure,String name,String cost,String explanation,List<String> nodes,double at) implements Serializable{}
    public record Decision(String kind,int towerId,Tower before,Tower after,int coinDelta,double cooldownReadyAt) implements Serializable{}
    public GameEngine(){world=Rules.world();path.addAll(world.path());log("BFS","Find the shortest route","O(V + E)","A FIFO frontier visits each walkable cell once; predecessors reconstruct the shortest path.",path.stream().map(p->p.col()+","+p.row()).toList());}
    public void setNoticeSink(Consumer<String> sink){notices=sink==null?m->{}:sink;}
    public List<Map<String,Object>> drainEvents(){List<Map<String,Object>> out=List.copyOf(events);events.clear();return out;}
    private void emit(String type,Object... fields){Map<String,Object> event=new LinkedHashMap<>();event.put("type",type);event.put("time",time);for(int i=0;i+1<fields.length;i+=2)event.put(String.valueOf(fields[i]),fields[i+1]);events.add(event);if(events.size()>500)events.removeFirst();}
    public Rules.World world(){return world;}public Tower selectedTower(){return towers.stream().filter(t->t.id==selectedTowerId).findFirst().orElse(null);}public Tower towerAt(int col,int row){return towers.stream().filter(t->t.col==col&&t.row==row).findFirst().orElse(null);}
    private double random(){seed=seed*1664525+1013904223;return (seed&0xffffffffL)/4294967296.0;}
    public void log(String structure,String op,String cost,String explain,List<String> nodes){operations.add(new Operation(structure,op,cost,explain,List.copyOf(nodes),time));long count=operations.stream().filter(o->o.structure.equals(structure)).count();if(count>12){for(int i=0;i<operations.size();i++)if(operations.get(i).structure.equals(structure)){operations.remove(i);break;}}}
    private void log(String s,String o,String c,String e){log(s,o,c,e,List.of());}
    public List<Operation> operationsFor(String structure){return operations.stream().filter(op->op.structure.equals(structure)).toList();}
    public void select(int id){selectedTowerId=towers.stream().anyMatch(t->t.id==id)?id:-1;}
    public boolean canPlace(TowerKind kind,int col,int row){return kind!=null&&col>=0&&col<17&&row>=0&&row<13&&world.buildable().contains(new BuildCell(col,row))&&coins>=kind.cost&&phase!=Phase.VICTORY&&phase!=Phase.DEFEAT&&towerAt(col,row)==null;}
    public boolean place(TowerKind kind,int col,int row){if(phase==Phase.VICTORY||phase==Phase.DEFEAT){notice("Restart the grove before building.");return false;}if(!canPlace(kind,col,row)){notice(coins<kind.cost?"You need "+kind.cost+" seeds for "+kind.name+".":"Choose an open tile beside the winding trail.");return false;}Tower t=new Tower(nextId++,kind,col,row,time);towers.add(t);coins-=kind.cost;selectedTowerId=t.id;emit("placement","id",t.id,"entityType",t.kind.name().toLowerCase(Locale.ROOT),"x",t.x(),"z",t.z());undo.push(new Decision("plant",t.id,null,t.copy(),-kind.cost,0));redo.clear();log("Stack","Push planting decision","O(1)","Store the tower and coin change so the build can be undone without rewinding combat.",List.of("tower "+t.id));return true;}
    public List<String> availableUpgrades(){Tower t=selectedTower();return t==null?List.of():Rules.upgradeOptions(t.kind,t.upgradeNode);}
    public boolean upgrade(String branch){Tower t=selectedTower();if(t==null)return false;if(!availableUpgrades().contains(branch)){notice("That growth branch is unavailable.");return false;}Upgrade u=Rules.upgrade(t.kind,branch);if(coins<u.cost){notice("You need "+u.cost+" seeds for this growth.");return false;}Tower before=t.copy();u.apply(t.stats);t.upgradeNode=branch;t.level++;t.invested+=u.cost;coins-=u.cost;emit("upgrade","id",t.id,"entityType",t.kind.name().toLowerCase(Locale.ROOT),"x",t.x(),"z",t.z());undo.push(new Decision("upgrade",t.id,before,t.copy(),-u.cost,0));redo.clear();log("Binary tree","Choose upgrade branch","O(u)","Depth-first search locates the current node; only its left or right child may be selected.",List.of(before.upgradeNode,branch));log("Stack","Push upgrade decision","O(1)","Save before and after tower state with the cost so undo preserves unrelated combat rewards.",List.of("tower "+t.id));return true;}
    public boolean sell(){Tower t=selectedTower();if(t==null)return false;Tower before=t.copy();int refund=(int)Math.floor(t.invested*.7);towers.remove(t);coins+=refund;selectedTowerId=-1;emit("sell","id",t.id,"x",t.x(),"z",t.z());undo.push(new Decision("sell",t.id,before,null,refund,time+Math.max(0,t.cooldown)));redo.clear();log("Stack","Push sale decision","O(1)","Undo restores the tower and elapsed cooldown while reversing only the sale refund.",List.of("tower "+t.id));return true;}
    public boolean undo(){Decision d=undo.peek();if(d==null){notice("No decision to undo.");return false;}if(coins-d.coinDelta<0){notice("Not enough seeds to undo that decision.");return false;}undo.pop();apply(d,false);redo.push(d);log("Stack","Pop undo; push redo","O(1) + O(T)","Reverse the last build decision without rewinding the simulation or seed rewards.",List.of("tower "+d.towerId));return true;}
    public boolean redo(){Decision d=redo.peek();if(d==null){notice("No decision to redo.");return false;}if(coins+d.coinDelta<0){notice("Not enough seeds to redo that decision.");return false;}redo.pop();apply(d,true);undo.push(d);log("Stack","Pop redo; push undo","O(1) + O(T)","Reapply a decision while keeping the current combat clock and live invaders.",List.of("tower "+d.towerId));return true;}
    private void apply(Decision d,boolean forward){Tower target=forward?d.after:d.before;Tower current=towers.stream().filter(t->t.id==d.towerId).findFirst().orElse(null);if(d.kind.equals("upgrade")&&current!=null&&target!=null){Stats live=current.stats;live.damage=target.stats.damage;live.range=target.stats.range;live.interval=target.stats.interval;live.multishot=target.stats.multishot;live.chain=target.stats.chain;current.level=target.level;current.upgradeNode=target.upgradeNode;current.invested=target.invested;}else{if(current!=null)towers.remove(current);if(target!=null){Tower restored=target.copy();if(d.kind.equals("sell"))restored.cooldown=Math.max(0,d.cooldownReadyAt-time);else restored.cooldown=.2;towers.add(restored);selectedTowerId=restored.id;}else selectedTowerId=-1;}coins+=forward?d.coinDelta:-d.coinDelta;}
    public void setDifficulty(Difficulty value){if(phase!=Phase.READY){notice("Difficulty is locked until the wave ends.");return;}difficulty=value;log("Decision","Set challenge","O(1)","The chosen balance profile is applied as this wave's enemies spawn.",List.of(value.label));}
    public void setTargetMode(TargetMode mode){Tower t=selectedTower();if(t==null||mode==null)return;t.mode=mode;log("Max heap","Change targeting priority","O(1)","The selected tower's next heap uses this ordering to choose its highest-priority live target.",List.of(mode.name()));}
    public void startWave(){if(phase!=Phase.READY)return;List<EnemySpec> specs=Rules.wave(wave,difficulty);queue.clear();for(EnemySpec s:specs)queue.offer(s);waveTotal=specs.size();waveKills=waveLeaked=0;waveDamage=0;spawnClock=.3;phase=Phase.WAVE;paused=false;emit("wave-start","wave",wave,"count",specs.size());log("Circular queue","Enqueue wave","O(n)","Pending invaders enter the fixed-size FIFO in authored wave order.",specs.stream().map(s->s.kind().name()).toList());}
    public void togglePause(){paused=!paused;}public void cycleSpeed(){speed=speed==1?2:speed==2?3:1;}
    public void update(double delta){if(paused||phase==Phase.VICTORY||phase==Phase.DEFEAT||delta<=0)return;accumulator+=Math.min(delta,.25)*speed;while(accumulator+1e-10>=STEP){step(STEP);accumulator-=STEP;if(phase==Phase.DEFEAT||phase==Phase.VICTORY){accumulator=0;break;}}}
    private void step(double dt){time+=dt;if(phase!=Phase.WAVE)return;if(!queue.isEmpty()){spawnClock-=dt;if(spawnClock<=0){EnemySpec s=queue.poll();spawn(s.kind());spawnClock+=s.delay();log("Circular queue","Dequeue next invader","O(1)","Remove the oldest enemy specification and advance the wrapping queue head.",List.of(s.kind().name()));}}
        for(Invader e:enemies){if(e.hp<=0)continue;double slow=e.slowUntil>time?e.slowFactor:1,surge=e.kind==EnemyKind.BOSS&&e.hp<e.maxHp*.5?1.42:1;e.velocity+=(e.speed*slow*surge-e.velocity)*(1-Math.exp(-dt*6));e.progress+=e.velocity*dt;int i=(int)e.progress;if(i>=path.size()-1){e.hp=0;e.escaped=true;health=Math.max(0,health-e.baseDamage);waveLeaked++;emit("leak","enemyId",e.id,"x",e.x,"z",e.z,"damage",e.baseDamage);continue;}BuildCell a=path.get(i),b=path.get(i+1);double f=e.progress-i;e.x=a.col()-8+(b.col()-a.col())*f;e.z=a.row()-6+(b.row()-a.row())*f;e.angle=Math.atan2(b.col()-a.col(),b.row()-a.row());}
        removeDead();if(health<=0){phase=Phase.DEFEAT;emit("defeat","wave",wave);return;}for(Tower t:towers){t.cooldown-=dt;if(t.cooldown<=0){Invader target=pickTarget(t);if(target!=null){emit("shot","towerId",t.id,"towerType",t.kind.name().toLowerCase(Locale.ROOT),"x",t.x(),"z",t.z(),"targetId",target.id);fire(t,target);t.cooldown=t.stats.interval;}else t.cooldown=.06;}}
        projectiles.filterInPlace(p->updateProjectile(p,dt));removeDead();if(queue.isEmpty()&&enemies.isEmpty())completeWave();}
    private void spawn(EnemyKind kind){double scale=1+(wave-1)*(kind==EnemyKind.BOSS?.12:.22),hp=Math.round(kind.hp*scale*difficulty.hp),sp=kind.speed*(1+(wave-1)*.018)*difficulty.speed;BuildCell start=path.getFirst();Invader e=new Invader(nextId++,kind,(int)hp,sp,Math.max(1,(int)Math.round(kind.reward*(1+wave*.075)*difficulty.reward)),kind.baseDamage,start.col()-8,start.row()-6,random());enemies.add(e);enemyIndex.put(e.id,e);emit("spawn","id",e.id,"type",e.kind.name().toLowerCase(Locale.ROOT),"x",e.x,"z",e.z);log("Binary search tree","Insert live invader","O(h), worst O(n)","Index the same mutable enemy object used by movement and projectiles.",List.of("ID "+e.id));}
    private Comparator<Invader> targetComparator(TargetMode mode){return switch(mode){case LAST->Comparator.comparingDouble((Invader e)->-e.progress).thenComparingInt(e->-e.id);case STRONGEST->Comparator.comparingDouble((Invader e)->e.hp).thenComparingDouble(e->e.progress);case WEAKEST->Comparator.comparingDouble((Invader e)->-e.hp).thenComparingDouble(e->e.progress);default->Comparator.comparingDouble((Invader e)->e.progress).thenComparingInt(e->-e.id);};}
    private MaxHeap<Invader> scanTargets(Tower t){MaxHeap<Invader> h=new MaxHeap<>(targetComparator(t.mode));for(Invader e:enemies)if(e.hp>0&&distance(t.x(),t.z(),e.x,e.z)<=t.stats.range)h.add(e);lastHeap=h;return h;}
    private Invader pickTarget(Tower t){MaxHeap<Invader> h=scanTargets(t);Invader target=h.poll();if(target!=null)log("Max heap","Extract highest-priority target","O(n + k log k)","Scan live enemies, heapify the k in-range targets by the tower's selected rule, then extract the root.",List.of("ID "+target.id,t.mode.name()));return target;}
    private void fire(Tower t,Invader target){t.targetId=target.id;t.firedAt=time;if(t.kind==TowerKind.LIGHTNING){Set<Integer> hit=new HashSet<>();List<Map<String,Object>> points=new ArrayList<>();points.add(Map.of("x",t.x(),"y",1.4,"z",t.z()));Invader current=target;for(int i=0;i<t.stats.chain&&current!=null;i++){hit.add(current.id);points.add(Map.of("x",current.x,"y",.5,"z",current.z));damage(current,t.stats.damage*Math.pow(.82,i),t.kind);MaxHeap<Invader> h=new MaxHeap<>(targetComparator(t.mode));Invader from=current;for(Invader n:enemies)if(n.hp>0&&!hit.contains(n.id)&&distance(from.x,from.z,n.x,n.z)<2.8)h.add(n);current=h.poll();}emit("lightning","towerId",t.id,"towerType","lightning","points",points,"x",t.x(),"z",t.z());return;}
        for(int i=0;i<t.stats.multishot;i++){Invader to=i==0?target:(lastHeap==null?null:lastHeap.poll());if(to==null)to=target;double duration=t.kind==TowerKind.CANNON?Math.max(.45,distance(t.x(),t.z(),to.x,to.z)/5.5):2.5;projectiles.add(new Projectile(nextId++,t.kind,t.id,to.id,t.x(),t.z(),to.x,to.z,t.stats.damage,duration));log("Singly linked list","Append projectile","O(1)","Add a fired seed at the list tail; impacts and expired shots unlink during one traversal.",List.of("projectile "+(nextId-1)));}}
    private boolean updateProjectile(Projectile p,double dt){p.age+=dt;if(p.kind==TowerKind.CANNON){double f=Math.min(1,p.age/p.duration),ox=p.x,oy=p.y,oz=p.z;p.x=p.originX+(p.targetX-p.originX)*f;p.z=p.originZ+(p.targetZ-p.originZ)*f;p.y=1.15*(1-f)+12.8*f*(1-f);p.vx=(p.x-ox)/dt;p.vy=(p.y-oy)/dt;p.vz=(p.z-oz)/dt;if(f>=1){for(Invader e:enemies){double d=distance(p.x,p.z,e.x,e.z);if(e.hp>0&&d<1.8)damage(e,p.damage*(1-.35*d/1.8),TowerKind.CANNON);}emit("impact","projectileType","cannon","x",p.x,"y",.4,"z",p.z,"radius",1.8,"targetId",p.targetId);return false;}}else{Invader e=enemyIndex.get(p.targetId);if(e==null||e.hp<=0||p.age>p.duration){log("Singly linked list","Remove expired projectile","O(P) traversal","The BST no longer returns a living target, so this linked-list node is discarded.",List.of("projectile "+p.id));return false;}double dx=e.x-p.x,dz=e.z-p.z,dy=.42-p.y,len=Math.sqrt(dx*dx+dy*dy+dz*dz),travel=p.speed*dt;if(len<travel+.16){damage(e,p.damage,p.kind);emit("impact","projectileType",p.kind.name().toLowerCase(Locale.ROOT),"x",e.x,"y",.4,"z",e.z,"radius",.35,"targetId",e.id);if(p.kind==TowerKind.FROST){e.slowUntil=Math.max(e.slowUntil,time+(e.kind==EnemyKind.BOSS?1.7:2.3));e.slowFactor=e.kind==EnemyKind.RESISTANT?.78:.55;}return false;}p.vx=dx/len*p.speed;p.vy=dy/len*p.speed;p.vz=dz/len*p.speed;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;}return Math.abs(p.x)<20&&Math.abs(p.z)<20&&p.age<5;}
    private void damage(Invader e,double amount,TowerKind source){if(e.hp<=0)return;if(e.kind==EnemyKind.RESISTANT&&(source==TowerKind.FROST||source==TowerKind.LIGHTNING))amount*=.45;double dealt=Math.min(e.hp,amount);e.hp-=dealt;waveDamage+=dealt;e.hitAt=time;emit("damage","enemyId",e.id,"x",e.x,"z",e.z,"damage",dealt,"source",source.name().toLowerCase(Locale.ROOT));}
    private void removeDead(){for(Iterator<Invader> it=enemies.iterator();it.hasNext();){Invader e=it.next();if(e.hp>0)continue;enemyIndex.remove(e.id);if(!e.escaped){coins+=e.reward;waveKills++;totalKills++;emit("death","enemyId",e.id,"enemyType",e.kind.name().toLowerCase(Locale.ROOT),"x",e.x,"z",e.z,"reward",e.reward);}it.remove();log("Binary search tree","Delete defeated invader","O(h), worst O(n)","Remove the dead enemy ID from the live index; successor replacement handles two-child nodes.",List.of("ID "+e.id));}}
    private void completeWave(){coins+=(int)Math.round((32+wave*7)*difficulty.reward);recordId++;history.put(recordId,new WaveRecord(recordId,wave,difficulty,waveKills,waveLeaked,health,coins));log("B-tree","Insert completed wave","O(log n)","Insert the wave record into a minimum-degree-2 B-tree; full nodes split and promote their median.",List.of("wave "+wave));emit("wave-complete","wave",wave,"reward",(int)Math.round((32+wave*7)*difficulty.reward));if(wave>=10){phase=Phase.VICTORY;emit("victory","health",health);notices.accept("The grove endured all ten waves.");}else{wave++;phase=Phase.READY;notices.accept("Wave "+(wave-1)+" survived. Reinvest your seeds for the next.");}}
    public void restart(){health=100;coins=200;wave=1;phase=Phase.READY;paused=false;speed=1;time=accumulator=spawnClock=waveDamage=0;waveKills=waveLeaked=waveTotal=totalKills=0;selectedTowerId=-1;towers.clear();enemies.clear();projectiles=new ProjectileList<>();queue=new CircularQueue<>(128);undo.clear();redo.clear();enemyIndex=new EnemyIndex<>();nextId=1;seed=2764293;world=Rules.world();path.clear();path.addAll(world.path());operations.clear();events.clear();log("BFS","Find the shortest route","O(V + E)","A FIFO frontier visits each walkable cell once; predecessors reconstruct the shortest path.",path.stream().map(p->p.col()+","+p.row()).toList());}
    public void save(){Path path=savePath();try(ObjectOutputStream out=new ObjectOutputStream(Files.newOutputStream(path))){out.writeObject(this);notices.accept("Grove saved on this device.");}catch(IOException ex){notices.accept("Could not save this grove: "+ex.getMessage());}}
    public void load(){try(ObjectInputStream in=new ObjectInputStream(Files.newInputStream(savePath()))){Object value=in.readObject();if(!(value instanceof GameEngine loaded))throw new IOException("This save is not a Sylva game.");copyFrom(loaded);notices.accept("Your saved grove has been restored.");}catch(IOException|ClassNotFoundException ex){notices.accept("No compatible saved grove was found.");}}
    private Path savePath(){return Path.of(System.getProperty("user.home"),".sylva-java-save");}
    private void copyFrom(GameEngine e){difficulty=e.difficulty;phase=e.phase;health=e.health;coins=e.coins;wave=e.wave;nextId=e.nextId;totalKills=e.totalKills;recordId=e.recordId;time=e.time;accumulator=e.accumulator;spawnClock=e.spawnClock;paused=e.paused;speed=e.speed;towers=e.towers;enemies=e.enemies;projectiles=e.projectiles;queue=e.queue;undo=e.undo;redo=e.redo;enemyIndex=e.enemyIndex;history=e.history;operations=e.operations;path=e.path;waveTotal=e.waveTotal;waveKills=e.waveKills;waveLeaked=e.waveLeaked;waveDamage=e.waveDamage;selectedTowerId=e.selectedTowerId;seed=e.seed;world=Rules.world();}
    private void readObject(ObjectInputStream in)throws IOException,ClassNotFoundException{in.defaultReadObject();world=Rules.world();notices=m->{};lastHeap=null;events=new ArrayList<>();}
    public List<Invader> heapTargets(){Tower t=selectedTower();if(t==null&&!towers.isEmpty())t=towers.getFirst();return t==null?List.of():scanTargets(t).values();}
    public List<Invader> indexedEnemies(){return enemyIndex.inorder();}
    public String btreeShape(){return history.describe();}
    private void notice(String message){notices.accept(message);}
    private static double distance(double x,double z,double ox,double oz){return Math.hypot(x-ox,z-oz);}
}
